  "· Device ID:": "· डिवाइस आईडी:",
  "\"Paid Events are managed exclusively by JiNANAM. If you wish to organize a paid event, please raise a support ticket. Our team will coordinate with you and create the event on your behalf.\"": "\"सशुल्क कार्यक्रम केवल JiNANAM द्वारा संचालित किए जाते हैं। यदि आप सशुल्क कार्यक्रम आयोजित करना चाहते हैं, तो कृपया सपोर्ट टिकट दर्ज करें। हमारी टीम आपसे समन्वय कर आपकी ओर से कार्यक्रम बनाएगी।\"",
  "(all fields mandatory)": "(सभी फ़ील्ड अनिवार्य)",
  "(all fields required *)": "(सभी फ़ील्ड आवश्यक *)",
  "(Auto-linked to current Temple/Jain Centre)": "(वर्तमान मंदिर/जैन केंद्र से स्वतः जुड़ा)",
  "(case-insensitive). Column marked": "(अक्षर-भेद रहित)। चिह्नित कॉलम",
  "(or tick Same as Current)": "(या 'वर्तमान के समान' पर टिक करें)",
  "* Linking members as volunteers will automatically display \"Volunteer at this Dharamshala\" on their public member profile card.": "* सदस्यों को स्वयंसेवक के रूप में जोड़ने पर उनके सार्वजनिक सदस्य प्रोफ़ाइल कार्ड पर \"इस धर्मशाला में स्वयंसेवक\" स्वतः दिखाई देगा।",
  "* Note: Rooms blocked or put on hold by the Admin will be displayed as \"booked\" to members, but remain flagged as Admin Blocked in backend control layers.": "* नोट: एडमिन द्वारा ब्लॉक किए गए या होल्ड पर रखे गए कमरे सदस्यों को \"बुक\" दिखाई देंगे, परंतु बैकएंड नियंत्रण परतों में वे एडमिन ब्लॉक्ड ही रहेंगे।",
  "**Monk Admins** have a global scope and are not restricted to specific organizations.": "**मुनि एडमिन** का दायरा वैश्विक होता है और वे किसी विशिष्ट संस्था तक सीमित नहीं होते।",
  "**Temple/Dharamshala/Jain Center Admins** must be mapped to at least one scoped organization. They can only CRUD resources inside their scoped organizations.": "**मंदिर/धर्मशाला/जैन केंद्र एडमिन** को कम से कम एक निर्दिष्ट संस्था से जोड़ा जाना आवश्यक है। वे केवल अपनी निर्दिष्ट संस्थाओं के भीतर ही संसाधन बना, देख, बदल या हटा सकते हैं।",
