  "Every meaningful screen listens to Socket.IO. When a monk moves, a visitor checks in, or a donation is verified — everyone with permission sees it within a heartbeat.": "प्रत्येक महत्वपूर्ण स्क्रीन Socket.IO से जुड़ी है। जब कोई मुनि आगे बढ़ते हैं, कोई आगंतुक चेक-इन करता है या कोई दान सत्यापित होता है — अनुमति प्राप्त सभी को तुरंत दिखाई देता है।",
  "Every module respects role-based permissions. Super Admins get everything; temple / dharamshala / jain-center admins see only their scope.": "प्रत्येक मॉड्यूल भूमिका-आधारित अनुमतियों का पालन करता है। सुपर एडमिन को सब कुछ मिलता है; मंदिर / धर्मशाला / जैन-केंद्र एडमिन को केवल अपना दायरा दिखता है।",
